SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now') AS extracted_at,activated_at FROM tipper_status WHERE id=1;
SELECT c.code AS competition,m.id,m.season_id,m.round_number,m.home_team_id,m.away_team_id,m.venue_id,m.external_afl_id,m.kickoff_at,m.date,m.status,m.home_points,m.away_points,s.year FROM matches m JOIN seasons s ON s.id=m.season_id JOIN competitions c ON c.id=s.competition_id WHERE c.code IN ('AFLM','AFLW') AND s.year BETWEEN 2020 AND 2026 ORDER BY c.code,s.year,m.kickoff_at,m.id;
SELECT c.code AS competition,ps.match_id,ps.player_id,ps.team_id,ps.goals,ps.behinds,ps.hitouts,ps.goal_assists,ps.inside_fifties,ps.marks_inside_fifty,ps.free_kicks_for,ps.free_kicks_against,ps.rebounds,ps.one_percenters,ps.marks,ps.clearances,ps.tackles FROM player_match_stats ps JOIN matches m ON m.id=ps.match_id JOIN seasons s ON s.id=m.season_id JOIN competitions c ON c.id=s.competition_id WHERE c.code IN ('AFLM','AFLW') AND s.year=2026 ORDER BY c.code,ps.match_id,ps.player_id;
SELECT c.code AS competition,p.player_id,p.team_id,p.off_pav,p.mid_pav,p.def_pav FROM player_season_pav p JOIN seasons s ON s.id=p.season_id JOIN competitions c ON c.id=s.competition_id WHERE c.code IN ('AFLM','AFLW') AND s.year=2025 ORDER BY c.code,p.player_id;
SELECT c.code AS competition,ml.match_id,ml.player_id,ml.team_id,ml.is_emergency,m.lineups_observed_at AS observed_at FROM match_lineups ml JOIN matches m ON m.id=ml.match_id JOIN seasons s ON s.id=m.season_id JOIN competitions c ON c.id=s.competition_id WHERE c.code IN ('AFLM','AFLW') AND s.year=2026 ORDER BY c.code,ml.match_id,ml.player_id;
SELECT c.code AS competition,SUM(m.home_points+m.away_points) AS points FROM matches m JOIN seasons s ON s.id=m.season_id JOIN competitions c ON c.id=s.competition_id WHERE c.code IN ('AFLM','AFLW') AND s.year BETWEEN 2021 AND 2025 AND m.status='Complete' AND m.home_points>=0 AND m.away_points>=0 GROUP BY c.code;
SELECT c.code AS competition,SUM(ps.inside_fifties) AS inside50 FROM player_match_stats ps JOIN matches m ON m.id=ps.match_id JOIN seasons s ON s.id=m.season_id JOIN competitions c ON c.id=s.competition_id WHERE c.code IN ('AFLM','AFLW') AND s.year BETWEEN 2021 AND 2025 AND m.status='Complete' AND m.home_points>=0 AND m.away_points>=0 GROUP BY c.code;
